BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-b8e1638016d22c3a49ae447d65c4' AND status='running' AND operation_hash='b8e1638016d22c3a49ae447d65c4db22cf0410e77bca01c05d790624395c8568' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT id,display_name,display_name_ca,brand,category_id,category_name,category_ids,unit_price,price_format,price_per_unit,price_per_unit_unit,available,published,description,ingredients,allergens,nutrition,conservation,description_ca,ingredients_ca,allergens_ca,nutrition_ca,detail_synced_at,synced_at,centers,center_prices,promo_name,promo_name_ca,promo_offer_price,promo_base_price,promo_end,offer_centers,raw,md5(to_jsonb(p)::text) AS source_row_md5 FROM public.plusfresc_products p WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)'))
      AND id COLLATE "C" > '032380' COLLATE "C" ORDER BY id COLLATE "C" LIMIT 100) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-b8e1638016d22c3a49ae447d65c4','operation_hash','b8e1638016d22c3a49ae447d65c4db22cf0410e77bca01c05d790624395c8568',
